SELECT (SELECT md5(coalesce(json_agg(r)::text,'[]')) FROM (SELECT table_name,column_name,data_type,is_nullable,column_default FROM information_schema.columns WHERE table_schema='machsan' ORDER BY table_name,ordinal_position) r) AS check_0, (SELECT md5(coalesce(json_agg(r)::text,'[]')) FROM (SELECT c.relname AS table_name,k.conname,k.contype,pg_get_constraintdef(k.oid) AS definition FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid WHERE k.connamespace='machsan'::regnamespace AND k.contype<>'n' ORDER BY c.relname,k.conname) r) AS check_1, (SELECT md5(coalesce(json_agg(r)::text,'[]')) FROM (SELECT tablename,indexname,indexdef FROM pg_indexes WHERE schemaname='machsan' ORDER BY tablename,indexname) r) AS check_2, (SELECT md5(coalesce(json_agg(r)::text,'[]')) FROM (SELECT t.tgname,t.tgenabled,pg_get_triggerdef(t.oid) AS definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relnamespace='machsan'::regnamespace AND NOT t.tgisinternal ORDER BY t.tgname) r) AS check_3, (SELECT md5(coalesce(json_agg(r)::text,'[]')) FROM (SELECT p.proname,p.prosrc,p.proconfig,p.prosecdef FROM pg_proc p WHERE p.pronamespace='machsan'::regnamespace ORDER BY p.proname) r) AS check_4;
